def split_words(text: str) -> list[str]:
    i = 0
    result = []
    current_word = []
    in_word = False
    quote_char = None
    n = len(text)

    while i < n:
        char = text[i]

        if quote_char == "'":
            if char == "'":
                quote_char = None
            else:
                current_word.append(char)
            i += 1
        elif quote_char == '"':
            if char == '"':
                quote_char = None
                i += 1
            elif char == '\\':
                if i + 1 >= n:
                    raise ValueError("Trailing backslash")
                next_char = text[i + 1]
                if next_char in ('"', '\\', '$', '`'):
                    current_word.append(next_char)
                    i += 2
                elif next_char == '\n':
                    i += 2
                else:
                    current_word.append('\\')
                    i += 1
            else:
                current_word.append(char)
                i += 1
        elif not in_word:
            if char in (' ', '\t', '\n'):
                i += 1
            elif char == '#':
                while i < n and text[i] != '\n':
                    i += 1
            elif char == "'":
                quote_char = "'"
                in_word = True
                i += 1
            elif char == '"':
                quote_char = '"'
                in_word = True
                i += 1
            elif char == '\\':
                if i + 1 >= n:
                    raise ValueError("Trailing backslash")
                next_char = text[i + 1]
                if next_char == '\n':
                    i += 2
                else:
                    current_word.append(next_char)
                    in_word = True
                    i += 2
            else:
                current_word.append(char)
                in_word = True
                i += 1
        else:  # in_word is True and no quote_char
            if char in (' ', '\t', '\n'):
                result.append("".join(current_word))
                current_word = []
                in_word = False
                i += 1
            elif char == "'":
                quote_char = "'"
                i += 1
            elif char == '"':
                quote_char = '"'
                i += 1
            elif char == '\\':
                if i + 1 >= n:
                    raise ValueError("Trailing backslash")
                next_char = text[i + 1]
                if next_char == '\n':
                    i += 2
                else:
                    current_word.append(next_char)
                    i += 2
            else:
                current_word.append(char)
                i += 1

    if quote_char:
        raise ValueError("Unclosed quote")
    if in_word:
        result.append("".join(current_word))

    return result
